SELECT COUNT(DISTINCT p.person_id) AS veteran_count FROM ads_person_basic_info p INNER JOIN ads_person_label_relation plr ON p.person_id = plr.person_id AND plr.delete_flag = 0 INNER JOIN ads_label_info li ON plr.label_id = li.label_id AND li.delete_flag = 0 INNER JOIN ads_residence_relation rr ON p.person_id = rr.person_id AND rr.delete_flag = 0 INNER JOIN ads_house_basic_info h ON rr.house_id = h.house_id AND h.delete_flag = 0 WHERE p.delete_flag = 0 AND h.street = '310110018' AND li.label_name IN ('参战退役军人', '参试退役军人（铀矿开采人员）');
